use std :: process :: Command ; use std :: time :: Instant ; use std :: fs ; fn benchmark_memory_usage () -> BenchmarkResult { let start = Instant :: now () ; let mut successful_memory_checks = 0 ; for _i in 0 .. 3 { match Command :: new ("./simple_repository_mathematical_atlas") . output () { Ok (output) => { if output . status . success () { match fs :: metadata ("repository_atlas_output/simple_complete_atlas.md") { Ok (metadata) => { if metadata . len () < 1024 * 1024 { successful_memory_checks += 1 ; } } Err (_) => { } } } } Err (_) => { } } } let duration = start . elapsed () ; if successful_memory_checks >= 2 { BenchmarkResult :: new ("Memory Usage" . to_string () , duration . as_millis () as u64 , 3 , true , None) } else { BenchmarkResult :: new ("Memory Usage" . to_string () , duration . as_millis () as u64 , 3 , false , Some (format ! ("Only {} successful memory checks out of 3" , successful_memory_checks))) } }